mkdir -p "$TMPDIR/scratch" && cat > "$TMPDIR/scratch/Scratch.java" << 'EOF'
import org.apache.commons.lang3.time.DurationFormatUtils;
import java.util.*;

public class Scratch {
    public static void main(String[] args) throws Exception {
        TimeZone tz = TimeZone.getTimeZone("UTC");
        Calendar start = new GregorianCalendar(tz);
        start.clear();
        start.set(2023, Calendar.JANUARY, 15, 0, 0, 0);
        Calendar end = new GregorianCalendar(tz);
        end.clear();
        end.set(2023, Calendar.MARCH, 10, 0, 0, 0);
        System.out.println("Jan15->Mar10 M/d: " + DurationFormatUtils.formatPeriod(start.getTimeInMillis(), end.getTimeInMillis(), "M'M 'd'D'", true, tz));

        // simple non-rollover case
        Calendar s2 = new GregorianCalendar(tz); s2.clear(); s2.set(2000, Calendar.JANUARY, 1, 0,0,0);
        Calendar e2 = new GregorianCalendar(tz); e2.clear(); e2.set(2000, Calendar.MARCH, 10, 5,6,7); e2.set(Calendar.MILLISECOND, 8);
        System.out.println("simple: " + DurationFormatUtils.formatPeriod(s2.getTimeInMillis(), e2.getTimeInMillis(), "yyyy-MM-dd'T'HH:mm:ss.SSS", true, tz));

        System.out.println("ISO 0: " + DurationFormatUtils.formatDurationISO(0));
        System.out.println("ISO 1day: " + DurationFormatUtils.formatDurationISO(86400000L));
        System.out.println("HMS 3661001: " + DurationFormatUtils.formatDurationHMS(3661001L));

        try {
            DurationFormatUtils.formatDuration(-1, "HH:mm:ss");
            System.out.println("no exception for negative!");
        } catch (IllegalArgumentException ex) {
            System.out.println("negative throws: " + ex.getMessage());
        }

        try {
            DurationFormatUtils.formatPeriod(10, 5, "HH:mm:ss");
            System.out.println("no exception for start>end!");
        } catch (IllegalArgumentException ex) {
            System.out.println("start>end throws: " + ex.getMessage());
        }

        try {
            DurationFormatUtils.formatDuration(0, "'unterminated");
            System.out.println("no exception for unterminated quote!");
        } catch (IllegalArgumentException ex) {
            System.out.println("unterminated quote throws: " + ex.getMessage());
        }

        try {
            DurationFormatUtils.formatDuration(0, "[[d]]");
            System.out.println("no exception for nested optional!");
        } catch (IllegalArgumentException ex) {
            System.out.println("nested optional throws: " + ex.getMessage());
        }

        try {
            DurationFormatUtils.formatDuration(0, "]");
            System.out.println("no exception for unopened optional close!");
        } catch (IllegalArgumentException ex) {
            System.out.println("unopened close throws: " + ex.getMessage());
        }

        try {
            DurationFormatUtils.formatDuration(0, "[d");
            System.out.println("no exception for unmatched optional!");
        } catch (IllegalArgumentException ex) {
            System.out.println("unmatched optional throws: " + ex.getMessage());
        }

        System.out.println("words 0: [" + DurationFormatUtils.formatDurationWords(0, true, true) + "]");
        System.out.println("words 1 day: [" + DurationFormatUtils.formatDurationWords(86400000L, true, true) + "]");
        System.out.println("words 1 sec no suppress: [" + DurationFormatUtils.formatDurationWords(1000L, false, false) + "]");

        System.out.println("duration big day: " + DurationFormatUtils.formatDuration(93784000L, "d'd 'HH:mm:ss"));
        System.out.println("padFalse: " + DurationFormatUtils.formatDuration(3661001L, "H:m:s.S", false));

        System.out.println("optional example: " + DurationFormatUtils.formatDuration(3600000L, "d'd'[H'h'm'm']s's'"));
        System.out.println("optional example zero: " + DurationFormatUtils.formatDuration(0L, "[d'd'H'h'm'm']s's'"));
        System.out.println("optional example brace: " + DurationFormatUtils.formatDuration(3600000L, "['{'d'}']HH':'mm"));
    }
}
EOF
javac -cp target/classes -d "$TMPDIR/scratch" "$TMPDIR/scratch/Scratch.java" && java -cp "$TMPDIR/scratch:target/classes" Scratch
